import React from 'react';
import './Perfil.css';
import { BiPencilSquare, BiTrash, BiCaretRightFill, BiBugFill } from 'react-icons/bi';

import usersData from '../data/userData';
import menuItems from '../data/menuItems';

const Perfil = () => {
  return (
    <div className="content-grid">
      {/* Menú usuarios izquierda */}
      <aside id="aside-izq">
        <h3>Usuarios</h3>
        <ul className="menu-perf">
          {usersData.map((user) => (
            <li key={user.id}>
              <img src={user.avatar} alt={`Avatar de ${user.name}`} />
              <a href="#">
                <i className="bi bi-person-circle" style={{ marginRight: "6px" }}></i>
                {user.name}
              </a>
            </li>
          ))}
        </ul>
      </aside>

      {/* Header */}
      <header>
        <h1>
          <a href="/">Mi Perfil</a>
        </h1>
        <p>Bienvenido a tu espacio personal</p>
      </header>

      {/* Contenido principal */}
      <main id="main-base">
        <div className="main-content">
          <div className="main-ima-perf">
            <img src="/user.svg" alt="Foto de perfil" />
          </div>
          <div className="descrip-perf">
            <h2>Usuario Ejemplo</h2>
            <p>
              Esta es la descripción del perfil del usuario. Aquí puedes colocar
              información relevante, biografía, intereses, y cualquier otro detalle
              que quieras compartir.
            </p>
          </div>
        </div>
      </main>

      {/* Menú derecha */}
      <aside id="aside-der">
        <h3>Menú</h3>
        <ul id="cont-der">
          {menuItems.map((item) => (
            <li key={item.id}>
              <a href={item.link}>{item.label}</a>
            </li>
          ))}
        </ul>
      </aside>

      {/* Footer */}
      <footer id="foot-base">
        <ul>
          <li><a href="#">Inicio</a></li>
          <li><a href="#">Acerca de</a></li>
          <li><a href="#">Contacto</a></li>
        </ul>
        <p>© 2025 Mi Perfil. Todos los derechos reservados.</p>
      </footer>
    </div>
  );
};

export default Perfil;
